  static int gotoFar(int mode) {
    int acc = 0;
    StringBuilder pad = new StringBuilder();
    for (int i = 0; i < 40; i++) {
      pad.append("padding-").append(i).append(';');
    }
    if (mode == 1) {
      acc += pad.length();
    } else if (mode == 2) {
      acc += pad.hashCode() & 1;
    } else if (mode == 3) {
      acc += pad.indexOf("7");
    } else if (mode == 4) {
      acc += pad.lastIndexOf("9");
    } else {
      acc = -1;
    }
    for (int i = 0; i < 40; i++) {
      pad.append("tail-").append(i).append(';');
    }
    if (acc >= 0) {
      acc += pad.length() / 2;
    }
    return acc;
  }
